import datetime
import unittest
from decimal import Decimal

import pennywise
from pennywise import Entry, ParseError, format_amount, format_entry, parse

BRIEF = """# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


class ParseTests(unittest.TestCase):
    def test_brief_example(self):
        self.assertEqual(
            parse(BRIEF),
            [
                Entry(datetime.date(2024, 3, 1), "salary", Decimal("2500.00"), "March pay"),
                Entry(datetime.date(2024, 3, 2), "groceries", Decimal("-42.50"), "weekly shop"),
                Entry(datetime.date(2024, 3, 5), "rent", Decimal("-900"), ""),
            ],
        )

    def test_field_types(self):
        (e,) = parse("2024-03-01 Salary 5 hi")
        self.assertIsInstance(e.date, datetime.date)
        self.assertIsInstance(e.amount, Decimal)
        self.assertEqual((e.category, e.note), ("salary", "hi"))

    def test_empty_and_blank_only(self):
        self.assertEqual(parse(""), [])
        self.assertEqual(parse("\n  \n\t\n# c\n   # indented comment\n"), [])

    def test_tabs_and_runs_of_spaces(self):
        (e,) = parse("2024-03-01\t\tfood \t -5 \t note")
        self.assertEqual((e.category, e.amount, e.note), ("food", Decimal("-5"), "note"))

    def test_note_whitespace_preserved_inside_trimmed_at_ends(self):
        (e,) = parse("2024-03-01 a 1   two  words\tand tab  \t ")
        self.assertEqual(e.note, "two  words\tand tab")

    def test_no_note_is_empty_string(self):
        (e,) = parse("2024-03-01 a 1   ")
        self.assertEqual(e.note, "")

    def test_crlf(self):
        es = parse("2024-03-01 a 1 x\r\n\r\n2024-03-02 b 2\r\n")
        self.assertEqual([e.note for e in es], ["x", ""])

    def test_no_trailing_newline(self):
        self.assertEqual(len(parse("2024-03-01 a 1")), 1)

    def test_equal_amounts(self):
        a, b, c = (parse("2024-03-01 a %s" % s)[0].amount for s in ("2500", "+2500", "2500.00"))
        self.assertEqual(a, b)
        self.assertEqual(b, c)

    def test_valid_amounts(self):
        for text, want in [("12", "12"), ("12.5", "12.5"), ("-0.99", "-0.99"), ("+0.1", "0.1"), ("0", "0")]:
            self.assertEqual(parse("2024-03-01 a " + text)[0].amount, Decimal(want), text)

    def test_invalid_amounts(self):
        for text in ["12.505", "1,000.00", "abc", ".5", "12.", "+-5", "--5", "1e3", "١٢", "5 5x"[:1] + "x"]:
            with self.assertRaises(ParseError, msg=text):
                parse("2024-03-01 a " + text)

    def test_invalid_dates(self):
        for text in ["2024-02-30", "2024-13-01", "2024-00-10", "2023-02-29", "24-03-01", "2024-3-1",
                     "2024/03/01", "2024-03-01x", "abcd-ef-gh", "٢٠٢٤-٠٣-٠١"]:
            with self.assertRaises(ParseError, msg=text):
                parse(text + " a 1")

    def test_leap_day_ok(self):
        self.assertEqual(parse("2024-02-29 a 1")[0].date, datetime.date(2024, 2, 29))

    def test_too_few_fields(self):
        for text in ["2024-03-01", "2024-03-01 a", "garbage"]:
            with self.assertRaises(ParseError, msg=text):
                parse(text)

    def test_error_line_counts_blank_and_comment_lines(self):
        text = "# c\n\n2024-03-01 a 1\n   \n# d\n2024-03-02 b oops\n"
        with self.assertRaises(ParseError) as ctx:
            parse(text)
        self.assertEqual(ctx.exception.line, 6)
        self.assertIn("line 6", str(ctx.exception))

    def test_first_error_reported(self):
        with self.assertRaises(ParseError) as ctx:
            parse("2024-03-01 a 1\nbad\nworse\n")
        self.assertEqual(ctx.exception.line, 2)

    def test_parse_error_is_value_error(self):
        self.assertTrue(issubclass(ParseError, ValueError))
        self.assertIs(pennywise.ParseError, ParseError)
        with self.assertRaises(ValueError):
            parse("nope")

    def test_impossible_date_message(self):
        with self.assertRaises(ParseError) as ctx:
            parse("2024-02-30 a 1")
        self.assertEqual(ctx.exception.line, 1)
        self.assertIn("line 1", str(ctx.exception))

    def test_entry_is_frozen(self):
        (e,) = parse("2024-03-01 a 1")
        with self.assertRaises(Exception):
            e.note = "x"


class FormatTests(unittest.TestCase):
    def test_format_amount(self):
        cases = {"1457.5": "1457.50", "12": "12.00", "-0.99": "-0.99", "-0.00": "0.00",
                 "0": "0.00", "+3": "3.00"}
        for text, want in cases.items():
            self.assertEqual(format_amount(Decimal(text)), want)

    def test_format_amount_huge(self):
        self.assertEqual(format_amount(Decimal("1" + "0" * 40)), "1" + "0" * 40 + ".00")

    def test_format_entry(self):
        d = datetime.date(2024, 3, 2)
        self.assertEqual(format_entry(Entry(d, "g", Decimal("-42.5"), "weekly shop")), "2024-03-02 g -42.50 weekly shop")
        self.assertEqual(format_entry(Entry(d, "g", Decimal("-42.5"), "")), "2024-03-02 g -42.50")


if __name__ == "__main__":
    unittest.main()
