import datetime
import unittest
from decimal import Decimal

from pennywise import balance, by_category, by_month, filter_entries, parse

D = datetime.date

TEXT = """2024-03-01 salary 2500.00 March pay
2024-03-02 Groceries -42.50 weekly shop
2024-04-01 groceries -10.10
2024-03-02 rent -900
2024-03-02 GROCERIES -1
"""


class ReportTests(unittest.TestCase):
    def setUp(self):
        self.entries = parse(TEXT)

    def test_balance(self):
        self.assertEqual(balance(self.entries), Decimal("1546.40"))
        self.assertIsInstance(balance(self.entries), Decimal)

    def test_balance_empty(self):
        self.assertEqual(balance([]), Decimal(0))
        self.assertIsInstance(balance([]), Decimal)

    def test_balance_exact(self):
        es = parse("2024-01-01 a 0.1\n2024-01-01 a 0.2\n")
        self.assertEqual(balance(es), Decimal("0.3"))

    def test_by_category(self):
        self.assertEqual(
            by_category(self.entries),
            {"salary": Decimal("2500"), "groceries": Decimal("-53.60"), "rent": Decimal("-900")},
        )
        self.assertEqual(by_category([]), {})

    def test_by_month(self):
        self.assertEqual(
            by_month(self.entries),
            {"2024-03": Decimal("1556.50"), "2024-04": Decimal("-10.10")},
        )
        self.assertEqual(by_month([]), {})

    def test_by_month_pads_year(self):
        self.assertEqual(list(by_month(parse("0999-01-05 a 1"))), ["0999-01"])

    def test_filter_none_returns_all_in_order(self):
        self.assertEqual(filter_entries(self.entries), self.entries)
        self.assertIsInstance(filter_entries(iter(self.entries)), list)

    def test_filter_category_case_insensitive(self):
        got = filter_entries(self.entries, category="gRoCeRiEs")
        self.assertEqual([e.amount for e in got], [Decimal("-42.50"), Decimal("-10.10"), Decimal("-1")])

    def test_filter_since_until_inclusive(self):
        got = filter_entries(self.entries, since=D(2024, 3, 2), until=D(2024, 3, 2))
        self.assertEqual([e.category for e in got], ["groceries", "rent", "groceries"])

    def test_filter_since_only_and_until_only(self):
        self.assertEqual(len(filter_entries(self.entries, since=D(2024, 4, 1))), 1)
        self.assertEqual(len(filter_entries(self.entries, until=D(2024, 3, 1))), 1)

    def test_filter_combined_and_empty(self):
        self.assertEqual(filter_entries(self.entries, category="rent", since=D(2024, 4, 1)), [])
        self.assertEqual(filter_entries([], category="x"), [])


if __name__ == "__main__":
    unittest.main()
